require_once __DIR__.'/../../config/database.php';require_once __DIR__.'/../../includes/session.php';require_once __DIR__.'/../../includes/functions.php';require_once __DIR__.'/../../includes/admin_layout.php';if(!is_admin_logged_in())redirect('../../index.php');if(($_SESSION['admin_role']??'admin')!=='admin'){http_response_code(403);exit('Administrator access required.');}$error='';$batch=$_SESSION['imported_student_credentials']??[];
if(($_GET['download']??'')==='template'){header('Content-Type:text/csv');header('Content-Disposition:attachment;filename="official-students-template.csv"');echo "student_id,full_name,department_code,department_name,course_code,course_name,year_level,section,email\n";exit;}if(($_GET['download']??'')==='credentials'&&$batch){header('Content-Type:text/csv');header('Content-Disposition:attachment;filename="imported-student-credentials.csv"');$o=fopen('php://output','w');fputcsv($o,['Student ID','Temporary Password']);foreach($batch as $x)fputcsv($o,[$x['code'],$x['password']]);fclose($o);exit;}
if($_SERVER['REQUEST_METHOD']==='POST'){if(!verify_csrf_token($_POST['csrf_token']??''))$error='Security token expired.';elseif(!verify_admin_password($conn,$_SESSION['admin_id'],$_POST['admin_password']??''))$error='Correct administrator password is required.';elseif(!isset($_FILES['csv'])||$_FILES['csv']['error']!==UPLOAD_ERR_OK||$_FILES['csv']['size']>2*1024*1024)$error='Upload a CSV file up to 2 MB.';else{$handle=fopen($_FILES['csv']['tmp_name'],'r');$header=array_map(fn($v)=>strtolower(trim($v)),fgetcsv($handle)?:[]);$required=['student_id','full_name','department_code','department_name','course_code','course_name','year_level','section','email'];if(array_diff($required,$header))$error='CSV columns do not match the official template.';else{$created=[];pg_query($conn,'BEGIN');try{while(($values=fgetcsv($handle))!==false){if(count($values)!==count($header))continue;$row=array_combine($header,$values);$student=strtoupper(trim($row['student_id']));$name=trim($row['full_name']);if(!$student||!$name)continue;$d=pg_query_params($conn,'INSERT INTO departments(code,name) VALUES($1,$2) ON CONFLICT(code) DO UPDATE SET name=EXCLUDED.name RETURNING id',[strtoupper(trim($row['department_code'])),trim($row['department_name'])]);$department=(int)pg_fetch_result($d,0,0);$c=pg_query_params($conn,'INSERT INTO courses(department_id,code,name) VALUES($1,$2,$3) ON CONFLICT(department_id,code) DO UPDATE SET name=EXCLUDED.name RETURNING id',[$department,strtoupper(trim($row['course_code'])),trim($row['course_name'])]);$course=(int)pg_fetch_result($c,0,0);$password=substr(strtoupper(bin2hex(random_bytes(6))),0,10);$qr=bin2hex(random_bytes(24));$insert=pg_query_params($conn,"INSERT INTO attendees(attendee_code,student_number,id_card_number,full_name,email,department_id,course_id,course,year_level,section,organization,password_hash,must_complete_profile,qr_token,account_status) VALUES($1,$1,$1,$2,$3,$4,$5,$6,$7,$8,concat_ws(' · ',$6,$7,$8),$9,TRUE,$10,'temporary') ON CONFLICT DO NOTHING RETURNING id",[$student,$name,trim($row['email'])?:null,$department,$course,trim($row['course_code']),trim($row['year_level']),trim($row['section']),password_hash($password,PASSWORD_DEFAULT),$qr]);if($insert&&pg_num_rows($insert))$created[]=['code'=>$student,'password'=>$password];}pg_query($conn,'COMMIT');$_SESSION['imported_student_credentials']=$created;$batch=$created;audit_log($conn,'official_student_roster_imported','student_import',null,['created'=>count($created)]);}catch(Throwable $e){pg_query($conn,'ROLLBACK');$error='Import failed; no rows were saved.';}fclose($handle);}}}
